<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';
import {getLearning,putLearning} from './learning-store';
import {defaultLevels,organizeBookmarks,removeGroup,removeLevel,type BookmarkGroup,type Importance} from './bookmark-model';
import type {SavedBookmark,BookSection} from './types';
const props=defineProps<{marks:SavedBookmark[];sections:BookSection[]}>(),emit=defineEmits<{update:[marks:SavedBookmark[]];navigate:[mark:SavedBookmark]}>();
const groups=ref<BookmarkGroup[]>([]),levels=ref<Importance[]>(defaultLevels.map(x=>({...x}))),group=ref('*'),level=ref('*'),tag=ref(''),chapter=ref('*'),book=ref('*'),sort=ref('importance'),name=ref(''),error=ref('');
const rows=ref(organizeBookmarks(props.marks));watch(()=>props.marks,v=>rows.value=organizeBookmarks(v));
const chapters=computed(()=>[...new Set(rows.value.map(r=>props.sections.find(s=>s.id===r.sectionId)?.group||r.sectionId))]);
const filtered=computed(()=>rows.value.filter(r=>(group.value==='*'||r.groupId===group.value)&&(level.value==='*'||r.importance===level.value)&&(book.value==='*'||r.bookId===book.value)&&(!tag.value||r.tags.some(t=>t.includes(tag.value)))&&(chapter.value==='*'||(props.sections.find(s=>s.id===r.sectionId)?.group||r.sectionId)===chapter.value)).sort((a,b)=>sort.value==='time'?b.createdAt.localeCompare(a.createdAt):levels.value.findIndex(l=>l.id===b.importance)-levels.value.findIndex(l=>l.id===a.importance)));
async function save(next=rows.value){rows.value=next;try{await putLearning('bookmarks',rows.value);emit('update',rows.value);error.value='';return true;}catch{error.value='保存失败，修改仍在窗口中，请重试。';return false;}}
async function metadata(){for(const g of groups.value)g.name=g.name.trim().slice(0,40)||'未命名分组';for(const l of levels.value)l.name=l.name.trim().slice(0,40)||'未命名等级';try{await putLearning('bookmark:groups',groups.value);await putLearning('bookmark:levels',levels.value);error.value='';}catch{error.value='分类保存失败，请重试。';}}
function edit(id:string,field:string,value:unknown){void save(rows.value.map(r=>r.id===id?{...r,[field]:value}:r));}
function add(kind:'group'|'level'){if(!name.value.trim())return;const entry={id:crypto.randomUUID(),name:name.value.trim().slice(0,40)};kind==='group'?groups.value.push(entry):levels.value.push({...entry,color:'#86c7dc'});name.value='';void metadata();}
async function del(kind:'group'|'level',id:string){if(kind==='group'){if(!await save(removeGroup(rows.value,id)))return;groups.value=groups.value.filter(g=>g.id!==id);}else if(id!=='normal'){if(!await save(removeLevel(rows.value,id)))return;levels.value=levels.value.filter(g=>g.id!==id);}await metadata();}
function reorder(i:number){if(i<2)return;[levels.value[i-1],levels.value[i]]=[levels.value[i],levels.value[i-1]];void metadata();}
onMounted(async()=>{groups.value=await getLearning('bookmark:groups',[]);levels.value=await getLearning('bookmark:levels',defaultLevels.map(x=>({...x})));await save();});
</script>
<template><section class="organized-bookmarks bookmark-list"><div class="bookmark-filters"><label>书籍<select v-model="book"><option value="*">全部书籍</option><option value="plex-programming">星轨编程</option></select></label><label>章节<select v-model="chapter"><option value="*">全部章节</option><option v-for="c in chapters" :key="c">{{c}}</option></select></label><label>分组<select aria-label="分组" v-model="group"><option value="*">全部分组</option><option value="">未分组</option><option v-for="g in groups" :value="g.id" :key="g.id">{{g.name}}</option></select></label><label>重要程度<select aria-label="重要程度" v-model="level"><option value="*">全部程度</option><option v-for="l in levels" :value="l.id" :key="l.id">{{l.name}}</option></select></label><label>标签<input v-model="tag" placeholder="筛选标签"/></label><label>排序<select v-model="sort"><option value="importance">重要程度</option><option value="time">创建时间</option></select></label></div>
<p v-if="!filtered.length">没有符合条件的书签。阅读时点击书签图标收藏当前位置。</p>
<article v-for="mark in filtered" :key="mark.id" class="organized-bookmark" :style="{'--mark-color':levels.find(l=>l.id===mark.importance)?.color||'#99a2ae'}"><h3>{{mark.title}}</h3><label>名称<input :value="mark.title" maxlength="100" @change="edit(mark.id,'title',($event.target as HTMLInputElement).value)"/></label><button @click="emit('navigate',mark)">回到原文</button><label>分组<select aria-label="分组" :value="mark.groupId" @change="edit(mark.id,'groupId',($event.target as HTMLSelectElement).value)"><option value="">未分组</option><option v-for="g in groups" :value="g.id">{{g.name}}</option></select></label><label>重要程度<select aria-label="重要程度" :value="mark.importance" @change="edit(mark.id,'importance',($event.target as HTMLSelectElement).value)"><option v-for="l in levels" :value="l.id">{{l.name}}</option></select></label><label>标签（逗号分隔）<input :value="mark.tags.join(', ')" @change="edit(mark.id,'tags',[...new Set(($event.target as HTMLInputElement).value.split(/[,，]/).map(s=>s.trim()).filter(Boolean))])"/></label><small>{{mark.createdAt?new Date(mark.createdAt).toLocaleString():'旧版书签 · 创建时间未记录'}}</small><button aria-label="删除书签" @click="save(rows.filter(r=>r.id!==mark.id))">删除</button></article>
<details><summary>管理分组与重要程度</summary><label>新名称<input v-model="name" maxlength="40"/></label><button @click="add('group')">新建分组</button><button @click="add('level')">新建重要程度</button><div v-for="g in groups" :key="g.id" class="bookmark-filters"><input aria-label="分组名称" v-model="g.name" @change="metadata"/><button @click="del('group',g.id)">删除分组（书签保留）</button></div><div v-for="(l,i) in levels" :key="l.id" class="bookmark-filters"><input aria-label="重要程度名称" v-model="l.name" @change="metadata"/><input aria-label="重要程度颜色" v-model="l.color" type="color" @change="metadata"/><button :disabled="i<2" @click="reorder(i)">降低排序</button><button :disabled="l.id==='normal'" @click="del('level',l.id)">删除等级（归为普通）</button></div></details><p v-if="error" role="alert">{{error}}<button @click="save();metadata()">重试</button></p></section></template>
<style>.bookmark-filters{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0}.organized-bookmarks label{display:inline-flex;flex-direction:column;gap:5px;font-size:12px;margin:6px}.organized-bookmarks input,.organized-bookmarks select{max-width:100%;padding:8px;font:inherit;color:inherit;background:#143144;border:1px solid #7392a7;border-radius:4px}.organized-bookmark{border-left:5px solid var(--mark-color);padding:12px;margin:14px 0;background:#122a3b}.organized-bookmark small{display:block;color:#b8c9d5}.organized-bookmarks details{margin-top:24px}</style>
